#include "harness.h"
#include "timerwheel.h"

int main(void) {
    tw_t w;
    uint32_t out[4];
    h_init();

    tw_init(&w, 8);
    CHECK_INT(tw_add(&w, 7, 3), 0);
    CHECK_INT(tw_add(&w, 9, 1), 0);
    CHECK_INT(tw_advance(&w, 1, out, 4), 1);
    CHECK_INT(out[0], 9);
    CHECK_INT(tw_advance(&w, 5, out, 4), 1);
    CHECK_INT(out[0], 7);
    CHECK_INT(tw_pending(&w), 0);
    return h_report();
}

