#include <stddef.h>
#include <stdint.h>

#define TW_MAX_SLOTS 32
#define TW_MAX_TIMERS 16

enum { TW_E_DELAY = -1, TW_E_FULL = -2, TW_E_DUP = -3, TW_E_NONE = -4 };

typedef struct {
    uint32_t id;
    uint64_t expire;
    uint32_t seq;
    int next; /* next timer in the same slot, -1 at the end */
    int used;
} tw_timer;

typedef struct {
    tw_timer timers[TW_MAX_TIMERS];
    int head[TW_MAX_SLOTS];
    int tail[TW_MAX_SLOTS];
    unsigned slots;
    uint64_t now;
    uint32_t seq;
    size_t pending;
} tw_t;

void tw_init(tw_t *w, unsigned slots);
int tw_add(tw_t *w, uint32_t id, uint32_t delay);
int tw_cancel(tw_t *w, uint32_t id);
int tw_reschedule(tw_t *w, uint32_t id, uint32_t delay);
size_t tw_advance(tw_t *w, uint32_t ticks, uint32_t *fired, size_t cap);
uint64_t tw_now(const tw_t *w);
size_t tw_pending(const tw_t *w);
int tw_next(const tw_t *w, uint32_t *delta);
size_t tw_list(const tw_t *w, uint32_t *ids, size_t cap);

#endif

